const masthead = document.getElementById('masthead');
const nav = document.getElementById('primary-nav');
const main = document.getElementById('main-content');
const colophon = document.getElementById('colophon');
if (!masthead || !nav || !main || !colophon) return false;

const isEnabled = typeof window.__ai4a11yFixLandmarks !== 'undefined' && window.__ai4a11yFixLandmarks.enabled;
if (!isEnabled) {
  return masthead.getAttribute('role') === null &&
         nav.getAttribute('role') === null &&
         main.getAttribute('role') === null &&
         colophon.getAttribute('role') === null;
}

return masthead.getAttribute('role') === 'banner' &&
       nav.getAttribute('role') === 'navigation' &&
       main.getAttribute('role') === 'main' &&
       colophon.getAttribute('role') === 'contentinfo';

const cookie = document.getElementById('cookie-notice');
const sidebar = document.getElementById('sidebar-widget');
const prose = document.getElementById('prose-links');
if (!cookie || !sidebar || !prose) return false;

// Cookie banner must not be misidentified as site banner
if (cookie.getAttribute('role') === 'banner' || cookie.getAttribute('role') === 'main') return false;

// Existing complementary role must be preserved
if (sidebar.getAttribute('role') !== 'complementary') return false;

// Prose block with links must not be classified as navigation
if (prose.getAttribute('role') === 'navigation' || prose.getAttribute('role') === 'main') return false;

return true;

const isEnabled = typeof window.__ai4a11yFixLandmarks !== 'undefined' && window.__ai4a11yFixLandmarks.enabled;
if (!isEnabled) return true;

// Landmark uniqueness and top-level constraints
const mains = document.querySelectorAll('[role="main"], main');
const banners = document.querySelectorAll('[role="banner"], header');
const footers = document.querySelectorAll('[role="contentinfo"], footer');

if (mains.length !== 1 || banners.length !== 1 || footers.length !== 1) return false;

const main = mains[0];
const banner = banners[0];
const footer = footers[0];

// Top-level verification: none of these landmarks should be contained in another
if (banner.closest('[role="main"], main')) return false;
if (footer.closest('[role="main"], main')) return false;
if (main.closest('[role="banner"], header')) return false;

// Interactive nav link checks: keyboard focusable, min target size, visible focus
const firstLink = document.querySelector('#primary-nav a');
if (!firstLink) return false;

const rect = firstLink.getBoundingClientRect();
if (rect.width < 24 || rect.height < 24) return false;
if (firstLink.textContent.trim() !== 'News') return false;

firstLink.focus();
const hasFocus = document.activeElement === firstLink;
const outlineWidth = parseFloat(window.getComputedStyle(firstLink).outlineWidth) || 0;
firstLink.blur();

return hasFocus && outlineWidth >= 2;
